260	      fieldsEditable: {
261	        title: !byId('title').disabled,
262	        summary: !byId('summary').disabled,
263	        body: !byId('body').disabled
264	      },
265	      saveBtnText: document.getElementById('save-btn').textContent,
266	      saveDisabled: document.getElementById('save-btn').disabled,
267	      cancelHidden: document.getElementById('cancel-btn').hidden,
268	      formEditing: document.getElementById('draft-form').classList.contains('editing'),
269	      bannerHidden: banner.hidden,
270	      bannerTitle: code ? code.textContent : null,
271	      bannerId: meta ? (meta.textContent.split('标识：')[1] || '') : '',
272	      statusText: status.textContent,
273	      statusKind: (status.className.match(/\\b(ok|err|warn)\\b/) || [])[1] || '',
274	      conflictHidden: document.getElementById('conflict-box').hidden,
275	      cards: cards,
276	      listCount: cards.length,
277	      listBusy: document.getElementById('article-list').getAttribute('aria-busy') !== 'false',
278	      listNoticeHidden: document.getElementById('list-notice').hidden,
279	      listNotice: document.getElementById('list-notice').textContent,
280	      emptyTip: document.getElementById('empty-tip').textContent
281	    };
282	  };
283	})();`;
